package cl.dynasty.nexusbeacon.platform.classic;
import java.util.Collections;import java.util.LinkedHashMap;import java.util.Locale;import java.util.Map;import org.bukkit.Color;import org.bukkit.Particle;import org.bukkit.configuration.ConfigurationSection;
public final class ClassicBeamStyleCatalog {private final Map<String,ClassicBeamStyle> styles;private final ClassicBeamStyle global;
 public ClassicBeamStyleCatalog(ConfigurationSection config,ClassicParticleResolver resolver){Map<String,ClassicBeamStyle> found=new LinkedHashMap<String,ClassicBeamStyle>();ConfigurationSection root=config.getConfigurationSection("beam-styles");if(root!=null)for(String id:root.getKeys(false)){ClassicBeamStyle style=parse(id,root.getConfigurationSection(id),resolver);if(style!=null)found.put(id.toLowerCase(Locale.ROOT),style);}styles=Collections.unmodifiableMap(found);global=parse("global",config.getConfigurationSection("visual-beam.global-style"),resolver);}
 public ClassicBeamStyle resolve(String id,String mode){if("GLOBAL".equalsIgnoreCase(mode))return global;if(id!=null){ClassicBeamStyle s=styles.get(id.toLowerCase(Locale.ROOT));if(s!=null)return s;}return "PLAYER".equalsIgnoreCase(mode)?null:global;}
 public int size(){return styles.size();}public Map<String,ClassicBeamStyle> getStyles(){return styles;}
 private static ClassicBeamStyle parse(String id,ConfigurationSection s,ClassicParticleResolver resolver){if(s==null)return null;String requested=s.getString("particle","END_ROD");ClassicParticleResolution resolution=resolver.resolve(requested);boolean degraded=false;if(!resolution.isResolved()&&"DUST".equalsIgnoreCase(requested)){resolution=resolver.resolve("REDSTONE");degraded=resolution.isResolved();}if(!resolution.isResolved())return null;return new ClassicBeamStyle(id,resolution.getParticle().get(),color(s.getString("color","NONE")),(float)s.getDouble("size",1.0D),degraded);}
 private static Color color(String raw){if(raw==null||"NONE".equalsIgnoreCase(raw))return null;String n=raw.toUpperCase(Locale.ROOT);if("AQUA".equals(n)||"CYAN".equals(n))return Color.AQUA;if("RED".equals(n))return Color.RED;if("LIME".equals(n)||"GREEN".equals(n))return Color.LIME;if("PURPLE".equals(n)||"MAGENTA".equals(n)||"FUCHSIA".equals(n))return Color.FUCHSIA;if("WHITE".equals(n))return Color.WHITE;return null;}}
